export const weatherPlaces={seoul:{name:'서울',latitude:37.5665,longitude:126.978,timezone:'Asia/Seoul'},busan:{name:'부산',latitude:35.1796,longitude:129.0756,timezone:'Asia/Seoul'},jeju:{name:'제주',latitude:33.4996,longitude:126.5312,timezone:'Asia/Seoul'},tokyo:{name:'도쿄',latitude:35.6762,longitude:139.6503,timezone:'Asia/Tokyo'},paris:{name:'파리',latitude:48.8566,longitude:2.3522,timezone:'Europe/Paris'}};
export function localHour(date,timeZone='Asia/Seoul'){const parts=new Intl.DateTimeFormat('en-GB',{timeZone,hourCycle:'h23',hour:'2-digit',minute:'2-digit'}).formatToParts(date);return Number(parts.find(p=>p.type==='hour').value)+Number(parts.find(p=>p.type==='minute').value)/60;}
const stops=[{h:0,label:'밤',sky:'#101b38',horizon:'#17274c',sun:'#bfd8f3',light:1.1,ambient:1.1},{h:5,label:'새벽',sky:'#233a67',horizon:'#55738d',sun:'#b8cce2',light:.9,ambient:.7},{h:7,label:'아침',sky:'#7395ac',horizon:'#efd6bd',sun:'#ffe4c9',light:2,ambient:1.25},{h:12,label:'낮',sky:'#8aacc0',horizon:'#dce5e5',sun:'#fff3e2',light:2.6,ambient:1.55},{h:16,label:'오후',sky:'#8494ab',horizon:'#c5c5c6',sun:'#f3d4b6',light:2,ambient:1.2},{h:18,label:'저녁',sky:'#233a67',horizon:'#947966',sun:'#e8b998',light:1.1,ambient:.85},{h:20,label:'밤',sky:'#101b38',horizon:'#17274c',sun:'#bfd8f3',light:1.1,ambient:1.1},{h:24,label:'밤',sky:'#101b38',horizon:'#17274c',sun:'#bfd8f3',light:1.1,ambient:1.1}];
export function skyAt(hour){const h=((hour%24)+24)%24;const i=stops.findIndex((s,j)=>j<stops.length-1&&h>=s.h&&h<stops[j+1].h),a=stops[i],b=stops[i+1];return{a,b,t:(h-a.h)/(b.h-a.h),label:a.label};}
export function weatherLabel(code){if(code===0)return'맑음';if(code<=3)return'구름';if([45,48].includes(code))return'안개';if([71,73,75,77,85,86].includes(code))return'눈';if(code>=95)return'뇌우';return'비';}
